def mergeAccounts(accounts):
    n = len(accounts)
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    first = {}
    for i, acc in enumerate(accounts):
        for e in acc[1:]:
            if e in first:
                ra, rb = find(i), find(first[e])
                if ra != rb:
                    parent[ra] = rb
            else:
                first[e] = i
    groups = {}
    for i, acc in enumerate(accounts):
        r = find(i)
        if r not in groups:
            groups[r] = (acc[0], set())
        groups[r][1].update(acc[1:])
    res = [[o] + sorted(s) for o, s in groups.values()]
    res.sort()
    return res
